import React, { useEffect, useState } from "react"
import Service from './header-icon-saq-v1-service.svg'
import Area from './header-icon-saq-v1-area.svg'
import Quote from './header-icon-saq-v1-quote.svg'
import Gallery from './header-icon-saq-v1-gallery.svg'
import Reviews from './header-icon-saq-v1-reviews.svg'
import GridRow from "../../../locust/composables/GridRow"
import { getFontMontserrat } from "../../../assets/fonts/FontMontserrat"
import "@fontsource/montserrat"
import "@fontsource/montserrat/600.css" 
import "@fontsource/montserrat/400.css" 
import Hide from "../../../locust/composables/Hide"
import { Center } from "../../../locust/composables/Center"
import HeaderBasicII from "../HeaderBasicII/HeaderBasicII"
import {Menu} from '@styled-icons/ionicons-solid/Menu'
import { css } from "glamor"
import { onHover } from "../../../locust/composables/Shared"
import Padding from "../../../locust/composables/Padding"
import { Line } from "../../../locust/components/Dividers"
import XY from "../../../locust/composables/XY"
import X from "../../../locust/composables/X"
import {Images} from '@styled-icons/boxicons-regular/Images'

const VERSION : number = 1

export default ( props : {
    mobile ?: boolean, 
    content : any, 
    logo ?: any, 
    //links : { href ?: string, onClick ?: ()=> void }[], 
    links : any, 
    sx ?: { linkContainer ?: any, logo ?: any  } 
    services ?: {
        value : any,
        space : number, 
        onClick ?: () => void,
    },
    mobileMenu ?: {
        icon ?: any, 
        onClick : () => void   
    }
}) => <HeaderServiceAreaQuoteV1 {...props}/>

export const HeaderServiceAreaQuoteV1 = ( props : {
    mobile ?: boolean, 
    content : any, 
    logo ?: any, 
    //links : { href ?: string, onClick ?: ()=> void }[], 
    links : any, 
    sx ?: { linkContainer ?: any, logo ?: any  } 
    services ?: {
        value : any,
        space : number, 
        onClick ?: () => void,
    },
    mobileMenu ?: {
        icon ?: any, 
        onClick : () => void   
    }
}) => {
    const space : number = 20
    const height : number = 70

    const [ links, setLinks ] = useState( props.content.links )

    useEffect(()=>{
        let updatedLinks : any = { ...props.content.links }
        Object.keys(props.links).forEach(( keyValue : string )=>{ 
            if( props.links[keyValue].onClick !== undefined )
                updatedLinks = { ...updatedLinks,
                [ keyValue ] : {
                    ...updatedLinks[keyValue],
                    onClick : props.links[keyValue].onClick 
                }
            }
         })
         setLinks( updatedLinks )
    },[])

    if( props.mobile ) return <div>
        <Line/>

        { links.quote && 
            <GridRow onClick={links?.quote?.onClick } height={ height } style={{ cursor : 'pointer', width : '100%', backgroundColor : '', transition : '200ms',[onHover] : { backgroundColor : 'whitesmoke' }}}>
                <Padding t={0} b={0}>    
                    <IconSAQ sx={{ icon : { marginLeft : -8,  marginRight : 6 }}} icon={ Quote } title={links.quote.title} subtitle={links.quote.subtitle }/>
                </Padding>
            </GridRow>
        }

        { links.area && 
            <GridRow height={ height } style={{ cursor : 'pointer', width : '100%', backgroundColor : '', transition : '200ms',[onHover] : { backgroundColor : 'whitesmoke' }}}>
                <Padding t={0} b={0}>    
                    <IconSAQ sx={{ icon : { marginRight : 10  } }} icon={ Area } title={links.area.title} subtitle={links.area.subtitle }/>
                </Padding>
            </GridRow>
        }
        
        { links.services && 
            <GridRow onClick={links?.services?.onClick } height={ height } style={{ cursor : 'pointer', width : '100%', backgroundColor : '', transition : '200ms',[onHover] : { backgroundColor : 'whitesmoke' }}}>
                <Padding t={0} b={0}>
                    <IconSAQ sx={{ icon : { marginLeft : -4, marginRight : 4 }}} icon={ Service } title={links.services.title} subtitle={links.services.subtitle }/>
                </Padding>
            </GridRow>
        }

        { links.gallery && 
            <GridRow onClick={ links?.gallery?.onClick } height={ height } style={{ cursor : 'pointer', width : '100%', backgroundColor : '', transition : '200ms',[onHover] : { backgroundColor : 'whitesmoke' }}}>
                <Padding t={0} b={0}>    
                    <IconSAQ sx={{ icon : {  marginLeft : -3, marginRight : 6 }, img : { height : 34 }}} icon={ Gallery } title={links.gallery.title} subtitle={links.gallery.subtitle }/>
                </Padding>
            </GridRow>
        }

        { links.reviews && 
            <GridRow onClick={links?.reviews?.onClick} height={ height } style={{ cursor : 'pointer', width : '100%', backgroundColor : '', transition : '200ms',[onHover] : { backgroundColor : 'whitesmoke' }}}>
                <Padding t={0} b={0}>    
                    <IconSAQ sx={{ icon : {  marginLeft : -3, marginRight : 6 }, img : { height : 34 }}} icon={ Reviews } title={links.reviews.title} subtitle={links.reviews.subtitle }/>
                </Padding>
            </GridRow>
        }
         
        
    </div>

    return (
        <div style={{ height : height, backgroundColor : 'white', width : '100%'}}> 
            <Hide on={850}>
                { props.logo && 
                    <GridRow height={ height } {...css({ float : 'left',cursor : 'pointer' })}>
                        <img src={props.logo} style={{ marginLeft : 10 }} height={ props?.sx?.logo?.height ? props.sx.logo.height : undefined } width={props?.sx?.logo?.width ? props.sx.logo.width : 200 } />
                    </GridRow>
                }

                { links.quote && 
                    <GridRow  onClick={links?.quote?.onClick } height={height} style={{ float : 'right',cursor : 'pointer' }}>
                        <IconSAQ w={ 120 + space } icon={ Quote } title={links.quote.title} subtitle={links.quote.subtitle }/>
                    </GridRow>
                }  
                
                { links.area && 
                    <GridRow onClick={links?.area?.onClick } height={height} style={{ float : 'right',cursor : 'pointer' }}>
                        <IconSAQ sx={{ icon : { marginRight : 10  } }} w={ 160 + space } icon={ Area } title={links.area.title} subtitle={links.area.subtitle }/>
                    </GridRow>
                }
                
                { links.services && 
                    <GridRow onClick={links?.services?.onClick } height={height} style={{ float : 'right',cursor : 'pointer' }}>
                        <IconSAQ sx={{ img : { marginTop : -3 }, icon : { marginRight : 4, }}} w={ 170 + space } icon={ Service } title={links.services.title} subtitle={links.services.subtitle }/>
                    </GridRow>
                }

                { links.gallery && 
                    <GridRow onClick={links?.gallery?.onClick } height={height} style={{ float : 'right',cursor : 'pointer' }}>
                        <IconSAQ sx={{ img : { marginTop : -3 }, icon : { marginRight : 4, }}} w={ 120 + space } icon={ Service } title={links.gallery.title} subtitle={links.gallery.subtitle }/>
                    </GridRow>
                }

            </Hide>
            <Hide b4={850}>
                <GridRow height={height} style={{ float : 'left', cursor : 'pointer' }}>
                    <img src={props.logo} style={{ marginLeft : 10 }} height={ props?.sx?.logo?.height ? props.sx.logo.height : undefined } width={props?.sx?.logo?.width ? props.sx.logo.width : 150 } />
                </GridRow>
                <GridRow height={height} style={{ float : 'right', marginRight : 16, cursor : 'pointer'  }}>
                    {props?.mobileMenu?.icon ? <>{props.mobileMenu.icon}</> : <Menu onClick={ props.mobileMenu?.onClick } {...css({ width : 30, color : 'black', cursor : 'pointer', [onHover] : { color : 'rgba(0,0,0,0.75)' }})}/>}    
                </GridRow>
            </Hide>
        </div>
    )
}

export const IconSAQ = ( props : {
    icon ?: any,
    height ?: number, 
    title ?: string, 
    subtitle ?: string, 
    w ?: number,
    sx ?: { icon ?: any, img ?: any }
}) => {

    const show : boolean = false
    const height : number = props.height ? props.height : 50

    return <>
        
        <div style={{ display : 'inline-block', width : props.w }}>
            <X align="left">
                <div style={{ display : 'inline-block', height, ...props?.sx?.icon }}>
                    <GridRow height={height}>
                        <img src={ props.icon } style={props?.sx?.img}/>
                    </GridRow>
                </div>
                <div style={{ display : 'inline-block', height, ...getFontMontserrat(), textTransform : 'uppercase' }}>
                    <div style={{ display : 'inline-block', height : height/2, width : '100%', fontWeight : 600, fontSize : 12, backgroundColor : !show ? '' : 'red' }}>
                        <GridRow align="bottom" height={height/2}>{props.title}</GridRow>
                    </div>
                    <div style={{ display : 'inline-block', height : height/2, width : '100%', fontWeight : 400, fontSize : 9, backgroundColor :  !show ? '' : 'blue' }}>
                        <GridRow align="top" height={height/2}>{props.subtitle}</GridRow>
                    </div>
                </div>
            </X>
        </div>
        
        
        
    </>
}