import React from "react"
import FiveStarFacebook from "./FiveStarFacebook"
import FiveStarYelp from "./FiveStarYelp"
import FiveStarGoogle from "./FiveStarGoogle"
import Hide from "../../composables/Hide"
import FiveStarNextDoor from "./FiveStarNextDoor"

const VERSION : number = 1

type FiveStarRatings = 'yelp' | 'nextdoor' | 'google' | 'facebook'

export default ( props : { gap ?: number, column ?: boolean, mobile ?: boolean }) => 
    <FiveStarDynamic {...props}/>

export const FiveStarDynamicSingle = ( props : { style ?: any, link ?: string, type : FiveStarRatings }) => {
    if(props.type === 'facebook')   return <FiveStarFacebook  {...{ link : props.link, style : props.style }}/>
    if(props.type === 'yelp')       return <FiveStarYelp  {...{ link : props.link, style : props.style }}/>
    if(props.type === 'nextdoor')   return <FiveStarNextDoor  {...{ link : props.link, style : props.style }}/>
    if(props.type === 'google')     return <FiveStarGoogle  {...{ link : props.link, style : props.style }}/>
    else return <></>
}

const FiveStarDynamic = ( props : { 
    gap ?: number, 
    column ?: boolean, 
    mobile ?: boolean 
    first ?: { link ?: string, type : FiveStarRatings }, 
    second ?: { link ?: string, type : FiveStarRatings }, 
    third?: { link ?: string, type : FiveStarRatings }, 

}) => {

    const gap : number = props.gap !== undefined ? props.gap : 10
    const rowOrColumn : any = props.column ? { display : 'block'} : {}
    const responsive : any = props.mobile ? { width : 90 } : {}

    const first : any = { 
        marginRight : props.column ? 0 : gap, 
        marginBottom : props.column ? gap : 0, 
        ...rowOrColumn,
        ...responsive,
    }
    const second : any = { 
        marginLeft : props.column ? 0 : gap, 
        marginRight : props.column ? 0 : gap, 
        marginBottom : props.column ? gap : 0, 
        marginTop : props.column ? gap : 0, 
        ...rowOrColumn,
        ...responsive,
    }

    const third : any = { 
        marginLeft : props.column ? 0 : gap, 
        marginTop : props.column ? gap : 0, 
        ...rowOrColumn,
        ...responsive,
    }

    return (
        <>  
            { props.first    !== undefined && <FiveStarDynamicSingle  {...{ link : props.first.link, style : first, type : props.first.type }}/> }
            { props.second   !== undefined && <FiveStarDynamicSingle {...{ link : props.second.link, style : second, type : props.second.type }}/> }
            { props.third    !== undefined && <FiveStarDynamicSingle  {...{ link : props.third.link, style : third, type : props.third.type }}/> }
        </>
    )
}

export const FiveStarDynamicRsp = (props : { 
    first ?: { link ?: string, type : FiveStarRatings }, 
    second ?: { link ?: string, type : FiveStarRatings }, 
    third?: { link ?: string, type : FiveStarRatings }, 
    gap ?: number, column ?: boolean, mobile ?: boolean, breakpoint ?: number  
}) => {
    const breakpoint : number = props.breakpoint ? props.breakpoint  : 400 
    return (
        <>
            <Hide on={ breakpoint }>
                <FiveStarDynamic {...props}/>
            </Hide>
            <Hide b4={ breakpoint }>
                <FiveStarDynamic {...props} mobile/>
            </Hide>
        </>
    )

}