import React from "react"
import DropShadow from "../../../locust/components/DropShadow"
import { getImagePlaceholder } from "../../shared/util"
import XY from "../../../locust/composables/XY"

export const ContainerTallBlock = ( props : {
    src ?: any 
    children ?: any, 
    height ?: number,
}) => <DropShadow>
    <div style={{ 
            marginBottom : 20, 
            height : (props.height ? props.height : 550), 
            width : 300, 
            backgroundColor : 'whitesmoke',
            backgroundImage : `url(${ props.src ? props.src : getImagePlaceholder()})`,
            backgroundRepeat : 'no-repeat',
            backgroundSize : 'cover',
            backgroundPosition : 'center'
        }}>
        <XY>
            <DropShadow>
                <div style={{ 
                    height : (props.height ? props.height : 550) - 30 - 30, 
                    width : 300 - 30 - 30, 
                    backgroundColor : 'rgba(255,255,255,0.8)'
                }}>
                    { props.children }
                </div>
            </DropShadow>
        </XY>
    </div>
</DropShadow>