import React from "react"
import { useEffect, useState } from "react"

const VERSION : number = 3

export const MobileMenuBasic = ( props : { toggle ?: boolean, children ?: any }) => {

    const [ toggle, setToggle ] = useState( props?.toggle ? props.toggle : false )
    
    useEffect(()=>{
        if(props?.toggle !== undefined) setToggle(props.toggle)
    },[ props?.toggle ])
    
    return (<>
        <div style={{ fontSize : 14, width : toggle ? 'max(350px,100vw)' : 0, overflow : 'hidden', backgroundColor : 'white', position : 'absolute', top : 115, height : 'calc(100vh - 100px)',right : toggle ? 0 : 'min(-100vw,-350px)', transition : '300ms' }}>
            { props.children }
        </div>
    </>)
}   