export const HeroBusBasicAndCarousel = ( props : {
    facebook ?: string, 
    yelp ?: string, 
    google ?: string, 
    images ?: any[],
    color ?: string, 
    onLead ?: () => void, 
    children ?: any, 
    height ?: number, 
}) => {

    const images : any[] = props.images ? props.images : [
        getImagePlaceholder(),
        getImagePlaceholder(),
        getImagePlaceholder(),
    ]

    const buttonStyleLeft = {
        width: "60px",
        height: "60px",
        background: 'none',
        borderRadius : '100%',
        border: '0px solid rgba(0,0,0,0.2)',
        //backgroundColor : 'whitesmoke',
        transform : 'translate(-20px)', 
        filter: `drop-shadow(0 0.2rem 0.25rem rgba(0, 0, 0, ${1}))`,
    };

    const buttonStyleRight = {
        width: "60px",
        height: "60px",
        background: 'none',
        borderRadius : '100%',
        border: '0px solid rgba(0,0,0,0.2)',
        //backgroundColor : 'whitesmoke',
        transform : 'translate(0px)', 
        filter: `drop-shadow(0 0.2rem 0.25rem rgba(0, 0, 0, ${1}))`,
    };

    const slideProps = {
        duration: 4000,
        transitionDuration : 600, 
        autoplay: true,
        //fade : true, 
        canSwipe  : true, 
        //arrows: false,
        infinite: true,
        easing: "ease",
        pauseOnHover : false, 
        //indicators: (i) => <div className="indicator">{i + 1}</div>
        //prevArrow: <button style={{ ...buttonStyleLeft }}><div style={{ marginLeft : 20, width : 40, height : 40 }}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#fff"><path d="M18.464 2.114a.998.998 0 0 0-1.033.063l-13 9a1.003 1.003 0 0 0 0 1.645l13 9A1 1 0 0 0 19 21V3a1 1 0 0 0-.536-.886zM17 19.091 6.757 12 17 4.909v14.182z"></path></svg></div></button>,
        //nextArrow: <button style={{ ...buttonStyleRight }}><div style={{ marginLeft : 20, width : 40, height : 40 }}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#fff"><path d="M5.536 21.886a1.004 1.004 0 0 0 1.033-.064l13-9a1 1 0 0 0 0-1.644l-13-9A.998.998 0 0 0 5 3v18a1 1 0 0 0 .536.886zM7 4.909 17.243 12 7 19.091V4.909z"></path></svg></div></button>
        prevArrow: <></>,
        nextArrow: <></>,
    };

    const height : number = props.height ? props.height : 600

    return (
        <div>
            <div style={{ height : height, width :'100%', backgroundColor : '' }}>
                <div className="slide-container" style={{ }}>
                    <Slide {...slideProps}>
                        { images.map(( image : any)=>{
                            return <div {...css({ height : height, width :'100%', backgroundColor : '', backgroundSize : '100%', backgroundPosition : 'center',backgroundImage : `url(${ image.url })`, backgroundRepeat : 'no-repeat',...image.style })}/>
                        })}
                    </Slide>
                </div>      
            </div>
            <div style={{ backgroundColor : '', width : '100%', height : height, marginTop : -height, position : 'absolute' }}>
                { props.children }
            </div>
        </div>   
    )
}


export const HeroBusBasicAndCarousel_BlockAndCenter = ( props : {
    gradient ?: boolean,
    facebook ?: string, 
    yelp ?: string, 
    google ?: string, 
    images ?: any[],
    color ?: string, 
    onLead ?: () => void, 
    height ?: number, 
    title : any, 
    subtitle : any, 
    tagline : any, 
}) => {
    return (
        <HeroBusBasicAndCarousel {...props}>
            <HeroBlockAndCenter {...{ ...props, height : props.height ? props.height : 600 }}/>
        </HeroBusBasicAndCarousel>
    )
}

const HeroBlockAndCenter = ( props : { gradient ?: boolean, height : number, color ?: string, onLead ?: () => void, title : any, subtitle : any, tagline : any  }) => {
    return (
        <>  
            <StackII>
                { props.gradient && <>
                    <div style={{ height : props.height, overflow : 'hidden'}}>
                        <div style={{ marginTop : -props.height/2, width : '100vw', height : '100%', background : 'linear-gradient(180deg, black 0%, transparent 100%)'}}>
                            
                        </div>
                    </div>
                    </>
                }

                { props.gradient && <>
                    <div style={{ height : props.height, overflow : 'hidden'}}>
                        <div style={{ marginTop : props.height/3, width : '100vw', height : '100%', background : 'linear-gradient(180deg, transparent 0%, black 100%)'}}>
                            
                        </div>
                    </div>
                    </>
                }
                    
                <Center>

                    <GridRow height={ props.height}>

                        <div style={{ marginTop : -20 }}/>
                        <Center><FiveStarGFYRsp {...{ ...props, gap : 10, breakpoint : 600 }}/></Center>
                        <Padding p={10}>
                            <div style={{ marginTop : 20, marginBottom : 20, display : 'inline-block', borderRadius : 16 , height : 200, lineHeight: 1.2, backgroundColor : 'rgba(0,0,0,0.4)', maxWidth : 600, fontWeight : 500, color : 'white', width : '100%', ...getFontPoppins(), fontSize : 40  }}>
                                <Padding>
                                    <span {...css({ display : 'block',  WebkitTextStrokeWidth : '3px', [on(550)]:{ fontSize : 45} })}>{ props.title }</span>
                                    <span {...css({ display : 'block', WebkitTextStrokeWidth : '2px', [on(550)]:{ fontSize : 30} })}>{ props.subtitle }</span>
                                    <span {...css({ display : 'block', color : props.color ? props.color : 'black', fontWeight : 500,  WebkitTextStrokeWidth : '2px', [on(550)]:{ fontSize : 30} })}>
                                        { props.tagline }
                                    </span>
                                </Padding>
                            </div>
                        </Padding>
                        <Center>
                            <DropShadow>
                                <GetFreeQuoteButton {...props} onClick={ props.onLead }/>
                            </DropShadow>
                        </Center>
                    </GridRow>
                </Center>
            </StackII>
        </>
    )
}


