const HeroTitleAndButton = ( props : { 
    spacing ?: { 
        top ?: {
            mobile : any,
            desktop : any, 
        }
    },
    gradient ?: boolean, 
    height : number, 
    color ?: string, 
    onLead ?: () => void, 
    title : any, 
    subtitle : any, 
    buttonText : any  
}) => {
    return (
        <>  
            <StackII>
                { props.gradient && <>
                    <div style={{ height : props.height, overflow : 'hidden'}}>
                        <div style={{ marginTop : -((props.height/4)*2), width : 'max(100vw,350px)', height : '100%', background : 'linear-gradient(180deg, black 0%, transparent 100%)'}}>
                            
                        </div>
                    </div>
                    </>
                }

                { props.gradient && <>
                    <div style={{ height : props.height, overflow : 'hidden'}}>
                        <div style={{ marginTop : (props.height/2), width : 'max(100vw,350px)', height : '100%', background : 'linear-gradient(180deg, transparent 0%, black 100%)'}}>
                            
                        </div>
                    </div>
                    </>
                }
                    
                <Center>

                        { !props.spacing &&  <SR s1={160} s2={20} breakpoint={500}/> }
                        { props.spacing?.top &&  <SR s1={props.spacing.top.desktop} s2={props.spacing.top.mobile} breakpoint={500}/> }
                        
                        
                        <Center><FiveStarGFYRsp {...{ ...props, gap : 10, breakpoint : 600 }}/></Center>
                        <Padding p={10}>
                            <div style={{ marginTop : 20, marginBottom : 20, display : 'inline-block', borderRadius : 16 , height : 200, lineHeight: 1.2, maxWidth : 700, fontWeight : 500, color : 'white', width : '100%', ...getFontPoppins(), fontSize : 40  }}>
                                <Padding>
                                    <span {...css({ textShadow : '0px 3.05328px 3.05328px rgba(0, 0, 0, 0.25)', display : 'block',  textAlign : 'center', fontWeight : 900, WebkitTextStrokeWidth : '0px', fontSize : 50, [on(720)]:{ fontSize : 40 }})}>{ props.title }</span>
                                    <Center>
                                        <span {...css({ marginTop : 20, lineHeight : 1.5, textAlign : 'center', maxWidth : 600, display : 'block', WebkitTextStrokeWidth : '0px', fontSize : 18, fontWeight : 400, [on(550)]:{ fontSize : 16} })}>{ props.subtitle }</span>
                                    </Center>
                                    {/* 
                                        <span {...css({ display : 'block', color : props.color ? props.color : 'black', fontWeight : 500,  WebkitTextStrokeWidth : '2px', [on(550)]:{ fontSize : 30} })}>
                                            { props.tagline }
                                        </span> 
                                    */}

                                    <Center>    
                                        <DropShadow>
                                            <GetFreeQuoteButtonOutline {...props} onClick={ props.onLead } style={{ marginTop : 30 }}/>
                                        </DropShadow>
                                    </Center>
                        
                                </Padding>
                            </div>
                        </Padding>
                        
                    
                </Center>
            </StackII>
        </>
    )
}

const GetFreeQuoteButton = ( props : { color ?: string, onClick ?: () => void, style ?: any   } ) => {
    return (<Button onClick={props.onClick} style={{ ...getFontPoppins(), textTransform : 'none', backgroundColor : props.color ? props.color : 'black', width : 250, height : 50, borderRadius : 8, ...props.style }}>
        <XY>
            <p style={{ color : 'white'}}>
                Get a Free Estimate
            </p>
        </XY>
    </Button>)
}

const GetFreeQuoteButtonOutline = ( props : { color ?: string, onClick ?: () => void, style ?: any   } ) => {
    return (<Button onClick={props.onClick} style={{ ...getFontPoppins(), border : '2px solid white', textTransform : 'uppercase', fontWeight : 800,  width : 250, height : 50, borderRadius : 0, backgroundColor : 'rgba(255,255,255,0.2)', ...props.style }}>
        <XY>
            <p style={{ color : 'white'}}>
                Get a Free Estimate
            </p>
        </XY>
    </Button>)
}